  'cdef.autoCompactHint': 'When a turn ends with more context than this, Harness summarizes the session and continues in a fresh thread seeded with the summary (like Compact): long sessions stop re-sending their whole history, which saves tokens. The history stays displayed.',
  'cdef.autoCompactOff': 'Off',
  'cdef.autoCompactRecommended': 'recommended',
  'cdef.idleCompact': 'Compact when you come back',
  'cdef.idleCompactHint': 'Claude\'s prompt cache lasts a few minutes (up to an hour). When you write to a session idle for longer, with at least this much context, Harness first summarizes it and your message runs in a fresh thread seeded with the summary: the history would be re-sent at full price anyway, so later turns get much cheaper. Costs one summary turn (a short wait) before the reply.',
  'cdef.smartResume': 'Smart resume',
  'cdef.smartResumeHint': "When you come back to a session whose cache expired (see above) with at least this much context, or after 5 minutes or more with twice as much, Harness first has Claude summarize the session for the message you just sent: the summary keeps exact what your message needs (files, commands, values, the plan in progress), and your message then runs in a fresh, much smaller thread. Measured on real returns: 38 to 67 % fewer tokens from 100k, and better kept details than the plain summary. Off = the rule above alone.",
  'cdef.protectSecrets': 'Protect the secrets',
  'cdef.protectSecretsHint': 'Claude’s tools refuse to read or edit the server’s secrets (secrets.json) and the SSH keys (~/.ssh), whatever the permission mode. It stops instructions hidden in a web page or an e-mail from simply reading them; a script written to open the file is not stopped - for content from outside, prefer a stricter permission mode on that topic.',
  'cdef.shortTitles': 'Short session titles',
  'cdef.shortTitlesHint': 'A new session is named in a few words from its first message (greetings and "can you…" removed). Off: the title is the start of the message. Renaming a session always wins.',
  'cdef.shortTitlesModel': 'Titles written by Claude',
  'cdef.shortTitlesModelHint': 'The smallest model names the subject (better titles). One quick call per new session, counted in your Claude plan.',
  'cdef.autoUpdate': 'Update Claude Code automatically',
  'cdef.autoUpdateHint': 'Off by default. On: when a newer stable release of Claude Code is out (one already used for some days, not the very latest), the server installs it once nothing has run for 10 minutes (no turn, no queued message, no cron job), and goes back to the previous one if it does not start. Checked every 6 hours; the result shows in the notifications.',
  'cdef.autoUpdateLast': 'Last update: {from} → {to}, {date}',
  'cdef.autoUpdateFailed': 'Update to {to} failed ({date})',
  'claude.permissionMode': 'Permission mode',
  'claude.mode.bypass': 'Full access (bypass permissions)',
  'claude.mode.bypassDesc': 'Claude runs any command and edits any file without asking, with the rights of the service user (root). Choose it only if this server is dedicated to Claude.',
  'claude.mode.recommendedVps': 'Dedicated VPS only',
  'claude.mode.acceptEdits': 'Accept file edits',
  'claude.mode.acceptEditsDesc': 'Claude can read and write files; other tools that need approval (most shell commands) are refused.',
  'claude.mode.default': 'Strict (refuse)',
  'claude.mode.defaultDesc': 'Every tool that needs approval is refused without asking. Safest, but Claude can do much less.',
  'claude.mode.ask': 'Ask me',
  'claude.mode.askDesc': 'Reading is free; anything else waits for your Allow or Deny, in the session, the notifications or Telegram. Denied after 30 min without an answer.',
  'claude.mode.note': 'Except in “Ask me”, nobody is asked: anything the mode does not allow is simply refused.',

