  'mcp.autoHint': 'Every loaded server costs tokens on each message and slows the start of a turn. When on, a session gets the servers its topic already used, the ones named in your message and the ones added to its topic; Claude can ask for another one (`maxxing mcp load`) and Harness continues by itself. A claude.ai connector needed loads everything, as before. The tools of the Harness Browser and of your Devices are always there when a turn may use them.',
