  'system.cleanup.trash': "Harness trash",
  'system.cleanup.trashDesc': "Deleted topics, sessions and files: they can no longer be restored afterwards.",
  'system.cleanupPrompt': "Audit the disk space of this server and help me free it up properly.\n\n1. State: `df -h` and `free -h`, then the biggest folders (`du -xh --max-depth=2 / 2>/dev/null | sort -h | tail -40`), and dig into the biggest ones. Settings -> System -> Free up space already handles the download caches, old component versions, the system journal, apt packages, video previews and the Harness trash: skip those.\n2. Go through every project and topic of the workspace: attachments, video and audio renders, exports, `node_modules`, Python environments, builds, heavy git repositories, forgotten worktrees, duplicates. Also look at the other tools' caches (`~/.cache/*`, downloaded models), logs and old files in `/tmp`.\n3. For each big item, find where it comes from: which project, tool or scheduled job created it (dates, content, the topic's memory, the crons), and whether it is still growing.\n4. Give me a table sorted by size: path, size, origin, comes back by itself or not, what you suggest (delete, move elsewhere, keep) and the space it frees.\n5. Delete nothing without my OK: ask me all your questions at once. For what keeps coming back, suggest fixing the cause (a size limit, a cleanup in the script or job that produces it).\n6. At the end, write what we decided (what stays, what gets cleaned) in the memory of the right topic.",
