  'notify.doneDesc': 'System notification when the tab is in the background, a small banner otherwise. Cron runs are not notified.',
  'team.notifySetting': "Team messages",
  'team.notifySettingDesc': "A new message of a Team chat that is not on screen pops up with a box to answer, or comes as a system notification when Harness is in the background (muted chats never notify).",
