  'stats.budget': 'Daily budget',
  'stats.budgetDesc': 'A ceiling in dollars per day for the whole server, at the price Claude Code reports for each turn (on a subscription: what the same turns would cost with an API key).',
  'stats.budgetField': 'Budget per day ($)',
  'stats.budgetFieldDesc': '0 = no budget. A notification at 80 %, an alert when it is reached. From then on, scheduled jobs and agents wait for tomorrow; your own messages and "Run now" still run.',
  'stats.budgetToday': 'Today',
  'stats.budgetSpent': '${spent} of ${limit}',
  'stats.budgetReached': 'Budget reached: scheduled jobs and agents wait for tomorrow.',
  'stats.limitRetry': 'Start again after the usage limit',
  'stats.limitRetryDesc': 'A scheduled job or an agent run stopped by the usage limit of your Claude plan starts again by itself once the limit resets (not when it resets more than a day later).',
  'stats.limitRetryDelay': 'Delay after the reset (seconds)',
  'stats.limitRetryDelayDesc': 'How long after the reset time it starts again, 0 to 3600.',
